"""Common utility functions for ABDM API requests."""import uuidfrom datetime import datetime, timedelta, timezone_token_cache = {    "access_token": None,    "expires_at": None,}def generate_request_id():    """    Generate a unique request ID for ABDM API calls.    Returns:        str: UUID string.    """    return str(uuid.uuid4())def generate_timestamp():    """    Generate the current UTC timestamp in ISO 8601 format expected by ABDM APIs.    Returns:        str: UTC timestamp in ISO 8601 format.    """    return (        datetime.now(timezone.utc)        .isoformat(timespec="milliseconds")        .replace("+00:00", "Z")    )def get_gateway_token():    """    Return a valid Gateway access token.    If the cached token expires within the next 3 minutes, a new token is    generated automatically.    Returns:        str: Gateway access token.    """    from auth import generate_gateway_token    now = datetime.now(timezone.utc)    expires_at = _token_cache["expires_at"]    refresh_required = (        _token_cache["access_token"] is None        or expires_at is None        or now >= (expires_at - timedelta(minutes=3))    )    if refresh_required:        # Token is about to expire. Generate a new one.        response = generate_gateway_token()        response.raise_for_status()        data = response.json()        _token_cache["access_token"] = data["accessToken"]        _token_cache["expires_at"] = (            now + timedelta(seconds=data["expiresIn"])        )    return _token_cache["access_token"]